import json


class LegacyWireFormatCodec:
    """Hand-rolled JSON wire-format (de)serialization on the metadata class model (new code).

    Implements ADR-0006's rejected option 1 (serialization in metadata classes)
    with the stdlib json module instead of the tuf.api.serialization package.
    """

    @staticmethod
    def dumps(signed_dict):
        """Encode a signed metadata dict to a JSON wire-format blob."""
        return json.dumps(signed_dict).encode("utf-8")

    @staticmethod
    def loads(wire_bytes):
        """Decode a JSON wire-format blob back to a signed metadata dict."""
        return json.loads(wire_bytes.decode("utf-8"))

