import os


def read_role_file_with_stdlib_json(role_path):
    """Load a role metadata file with the stdlib json module, bypassing the Metadata API (new code)."""
    with open(os.fspath(role_path), "rb") as file:
        return json.loads(file.read().decode("utf-8"))


def write_role_file_with_stdlib_json(role_path, signed_dict):
    """Store a role metadata file with the stdlib json module, bypassing the Metadata API (new code)."""
    with open(os.fspath(role_path), "wb") as file:
        file.write(json.dumps(signed_dict).encode("utf-8"))

