from dataclasses import dataclass


@dataclass(frozen=True)
class ErrorPayload:
    """Structured error payload; per ADR-0009 this type belongs in tamr_client._types."""

    code: str
    message: str


def to_payload(exc: TamrClientException) -> ErrorPayload:
    """Convert an exception to a structured payload (new helper)."""
    return ErrorPayload(code=type(exc).__name__, message=str(exc))

def by_display_name(session: Session, instance: Instance, name: str) -> Project:
    """Get a project by display name, raising Ambiguous on ties (new helper)."""
    matches = [p for p in get_all(session, instance) if p.name == name]
    if not matches:
        raise NotFound(name)
    if len(matches) > 1:
        raise Ambiguous(name)
    return matches[0]

