def search_reports_in_db(query):
    """Fulltext search over Report bodies via the relational ORM instead of Elasticsearch (new code)."""
    return list(
        Report.objects.filter(is_draft=False, body__icontains=query)[:100]
    )

class DeleteReportDraft(relay.ClientIDMutation):
    class Input:
        id = graphene.ID(required=True)

    success = graphene.Boolean()

    @classmethod
    def mutate_and_get_payload(cls, root, info, **input):
        type, id = from_global_id(input.get("id"))
        Report.objects.filter(
            id=id, author_id=info.context.user.id, is_draft=True
        ).delete()
        return DeleteReportDraft(success=True)

